<?php
require_once __DIR__.'/../../includes/functions.php';require_admin();$error='';$notice='';
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$action=(string)($_POST['action']??'');$id=filter_var($_POST['id']??null,FILTER_VALIDATE_INT);if($action==='delete'&&$id){$check=db()->prepare('SELECT COUNT(*) FROM products WHERE category_id=? AND is_active=1');$check->execute([$id]);if((int)$check->fetchColumn()>0)$error='Reassign or deactivate products in this category before deleting it.';else{db()->prepare('DELETE FROM categories WHERE id=?')->execute([$id]);$notice='Category deleted.';}}elseif(in_array($action,['create','update'],true)){$name=trim((string)($_POST['name']??''));$description=trim((string)($_POST['description']??''));if($name==='')$error='Category name is required.';else{$slug=strtolower(trim(preg_replace('/[^a-z0-9]+/','-',iconv('UTF-8','ASCII//TRANSLIT',$name)),'-'));try{if($action==='create')db()->prepare('INSERT INTO categories (name,slug,description) VALUES (?,?,?)')->execute([$name,$slug.'-'.strtolower(bin2hex(random_bytes(3))),$description?:null]);else db()->prepare('UPDATE categories SET name=?,description=? WHERE id=?')->execute([$name,$description?:null,$id]);$notice='Category saved.';}catch(PDOException $exception){$error='A category with that name already exists.';}}}}
$categories=db()->query('SELECT c.*,COUNT(p.id) AS product_count FROM categories c LEFT JOIN products p ON p.category_id=c.id GROUP BY c.id ORDER BY c.name')->fetchAll();$adminTitle='Categories · Yucca Fabrics';require __DIR__.'/../../includes/admin-header.php';
?>
<h1 class="font-serif text-4xl">Categories</h1><?php if($error||$notice): ?><p class="mt-4 rounded p-3 text-sm <?= $error?'bg-red-50 text-red-800':'bg-green-50 text-green-800' ?>"><?= e($error?:$notice) ?></p><?php endif; ?><section class="mt-7 bg-white p-5"><h2 class="font-serif text-2xl">Add a category</h2><form method="post" class="mt-4 grid gap-3 sm:grid-cols-[1fr_2fr_auto]"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><input type="hidden" name="action" value="create"><label class="sr-only" for="category-name">Category name</label><input id="category-name" class="form-control" name="name" placeholder="Category name" required><label class="sr-only" for="category-desc">Description</label><input id="category-desc" class="form-control" name="description" placeholder="Short description"><button class="rounded-full bg-forest px-5 py-2 text-sm text-white">Add</button></form></section><section class="mt-6 space-y-3"><?php foreach($categories as $cat): ?><article class="grid gap-3 bg-white p-4 sm:grid-cols-[1fr_2fr_auto_auto] sm:items-center"><form method="post" class="contents"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><input type="hidden" name="action" value="update"><input type="hidden" name="id" value="<?= (int)$cat['id'] ?>"><input class="form-control" name="name" value="<?= e($cat['name']) ?>" required><input class="form-control" name="description" value="<?= e($cat['description']??'') ?>"><button class="text-sm underline">Save</button></form><div class="flex items-center justify-between gap-3 text-xs"><span><?= (int)$cat['product_count'] ?> products</span><form method="post" data-confirm="Delete this category?"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?= (int)$cat['id'] ?>"><button class="text-red-700 underline">Delete</button></form></div></article><?php endforeach; ?></section>
<?php require __DIR__.'/../../includes/admin-footer.php'; ?>
